"""P0.1 concurrency on disposable SIDE1 PostgreSQL; test identities, not Supabase Auth.
Run: python tests/p01_postgres_concurrencia.py (server 127.0.0.1:55447).
Creates a new side_p01_<uuid> database only, never connects to remote hosts.
"""
import sys,pathlib,uuid,json,threading
sys.path.insert(0,str(pathlib.Path('tests/.python-deps').resolve()))
import psycopg
from psycopg import sql
from psycopg.types.json import Jsonb
DSN='host=127.0.0.1 port=55447 user=side_p01 dbname=postgres'
name='side_p01_'+uuid.uuid4().hex[:12]
with psycopg.connect(DSN,autocommit=True) as c:
 c.execute(sql.SQL('create database {}').format(sql.Identifier(name)))
DSN=f'host=127.0.0.1 port=55447 user=side_p01 dbname={name}'
root=pathlib.Path.cwd()
base='''do $$begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon; end if; if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if; if not exists(select 1 from pg_roles where rolname='service_role') then create role service_role; end if; end$$; create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.uid',true),'')::uuid$$;
create function auth.role() returns text language sql stable as $$select current_setting('test.role',true)$$;
create table auth.users(id uuid primary key,raw_user_meta_data jsonb,email text);
create table empresas(id bigint generated by default as identity primary key,nombre_legal text,nombre_comercial text,caja_inicial numeric,caja_actual numeric,ciclo_actual integer default 1,reputacion numeric);
create table decisiones_catalogo(id serial primary key,categoria text,categoria_nombre text,decision_id text,decision_nombre text,tipo text,es_recurrente boolean,es_obligatoria boolean,costo_base numeric,descripcion text,activo boolean);
create table decisiones_opciones(id serial primary key,decision_id integer,opcion_id text,etiqueta text,descripcion text,costo numeric,capacidad_diaria numeric,tasa_liquidacion numeric,canal text,distrito text,demanda_factor numeric,compromiso_ciclos integer,activo boolean default true);
create table empresas_decisiones(id serial primary key,empresa_id bigint,ciclo integer,decision_id integer,opcion_id integer,cantidad integer,costo_total numeric,enviada boolean,updated_at timestamptz default now());'''
paths=['supabase/migrations/supabase_migration.sql','supabase/migrations/supabase_game_lifecycle.sql','supabase/migrations/supabase_student_admission.sql','supabase/migrations/20260930_preservar_opciones_decisiones.sql','supabase/migrations/20261009_sala_espera_identidad_exacta.sql','docs/sql/20261023_despliegue_cierre_v19.sql','supabase/migrations/20261026_cierre_sin_expulsion_automatica.sql','supabase/migrations/20261027_corregir_ventas_generales.sql','supabase/migrations/20261028_cierre_servidor.sql','supabase/migrations/20261030162649_side_pedidos_autoritativos.sql','supabase/migrations/20261030165204_side_cierre_revision_pedidos.sql','supabase/migrations/20261030173958_ordenes_confirmacion_atomica.sql']
prof='11111111-1111-1111-1111-111111111111'
with psycopg.connect(DSN,autocommit=True) as c:
 c.execute(base)
 c.execute("create schema side_private; alter table if exists participantes add column if not exists expulsada_at timestamptz")
 for p in paths:
  text=(root/p).read_text(encoding='utf-8-sig')
  c.execute(text)
 c.execute("alter table participantes add column if not exists expulsada_at timestamptz")
 c.execute('alter function public.guardar_estado_estudiante(text,text,text,jsonb,bigint) set schema side_private; alter function side_private.guardar_estado_estudiante(text,text,text,jsonb,bigint) rename to side_ident_guardar_estado')
 c.execute((root/'supabase/migrations/20261030180225_entrega_operativa_autorizada.sql').read_text(encoding='utf-8-sig'))
 c.execute("insert into auth.users values(%s,'{}','teacher@example.invalid')",[prof]);c.execute("select set_config('test.uid',%s,false)",[prof])
 cfg={'lifecycleVersion':2,'cycleCloseMode':'manual','integrationDurationMinutes':5,'integrationMinutes':0,'cycles':2,'roundHours':0,'roundMinutes':10,'enabledEvents':[],'materialRulesVersion':'receipts-v1','materialLeadTimeDays':0,'materialPaymentMode':'cash','deliveryPolicy':'explicit_provider_event_v1'}
 game=c.execute("insert into partidas(profesor_id,nombre,configuracion) values(%s,'P01 concurrency',%s) returning id,codigo",[prof,Jsonb(cfg)]).fetchone();gid,code=game
 joined=c.execute("select public.ingresar_empresa(%s,'A','A')",[code]).fetchone()[0];eid=joined['empresa_id']
 joined_b=c.execute("select public.ingresar_empresa(%s,'B','B')",[code]).fetchone()[0];eid_b=joined_b['empresa_id']
 c.execute("update partidas set estado='activa',configuracion=configuracion||jsonb_build_object('runtime',jsonb_build_object('round',1,'phase','decisions','status','running','running',true,'startedAt',now()-interval '141 seconds','duration',600)) where id=%s",[gid])
 c.execute("select set_config('test.role','authenticated',false)")
 st={'CUERO':{'round':1,'quantities':{}},'ACCESORIOS':{'round':1,'quantities':{}},'HILO':{'round':1,'quantities':{'hilo_std':2600,'hilo_prem':1000}}}
 snap={'round':1,'decisions_submitted':True,'decision_state':{'__cyclePlans':{'1':{'state':st}}}}
 result=c.execute("select public.guardar_estado_estudiante(%s,'A','A',%s,0)",[code,Jsonb(snap)]).fetchone()[0];assert result['success'],result
 orders=dict(c.execute('select sku,order_id from side_material_orders_v1 where empresa_id=%s',[eid]).fetchall());assert len(orders)==2

barrier=threading.Barrier(2);confirmations=[]
def confirm():
 try:
  with psycopg.connect(DSN) as c:
   c.execute("set local lock_timeout='5s'; set local statement_timeout='10s'")
   c.execute("select set_config('test.uid',%s,true),set_config('test.role','authenticated',true)",[prof]);c.execute('set local role authenticated');barrier.wait(timeout=10)
   value=c.execute("select public.guardar_estado_estudiante(%s,'B','B',%s,0)",[code,Jsonb(snap)]).fetchone()[0];c.commit();confirmations.append(('ok',value))
 except Exception as e:confirmations.append(('error',getattr(e,'sqlstate',None),str(e).splitlines()[0]))
threads=[threading.Thread(target=confirm) for _ in range(2)]
for t in threads:t.start()
for t in threads:t.join(15);assert not t.is_alive(),'confirmation blocked'
print('confirmaciones',json.dumps(confirmations,ensure_ascii=False))
assert len(confirmations)==2 and all(x[0]=='ok' for x in confirmations),confirmations
assert sum(x[1].get('success') is True for x in confirmations)==1 and sum(x[1].get('code')=='ESTADO_DESACTUALIZADO' for x in confirmations)==1,confirmations
with psycopg.connect(DSN) as c:assert c.execute('select count(*) from side_material_orders_v1 where empresa_id=%s',[eid_b]).fetchone()[0]==2

def run_pair(label, calls):
 barrier=threading.Barrier(2);result=[]
 def worker(args):
  try:
   with psycopg.connect(DSN) as c:
    c.execute("set local lock_timeout='5s'; set local statement_timeout='10s'");c.execute("select set_config('test.uid',%s,true),set_config('test.role','authenticated',true)",[prof]);c.execute('set local role authenticated');barrier.wait(timeout=10)
    val=c.execute('select public.side_registrar_entrega_proveedor_v1(%s,%s,%s,%s)',args).fetchone()[0];c.commit();result.append(('ok',val))
  except Exception as e:result.append(('error',getattr(e,'sqlstate',None),str(e).splitlines()[0]))
 threads=[threading.Thread(target=worker,args=(x,)) for x in calls]
 for t in threads:t.start()
 for t in threads:t.join(15);assert not t.is_alive(),label+' blocked'
 print(label,json.dumps(result,ensure_ascii=False));return result
same=run_pair('misma clave',[(gid,orders['hilo_std'],'same',700)]*2)
assert len(same)==2 and all(x[0]=='ok' for x in same) and sorted(x[1]['reused'] for x in same)==[False,True],same
over=run_pair('parciales exceden',[(gid,orders['hilo_prem'],'over-a',600),(gid,orders['hilo_prem'],'over-b',600)])
assert sum(x[0]=='ok' for x in over)==1 and sum(x[0]=='error' and 'superior' in x[2] for x in over)==1,over
with psycopg.connect(DSN) as c:
 rows=c.execute('select order_id,sum(quantity),count(*) from side_material_receipts_v1 group by order_id order by order_id').fetchall();print('saldos',rows)
 assert sorted((int(q),n) for _,q,n in rows)==[(600,1),(700,1)]
print('PASS PostgreSQL real: eventos idempotentes y exceso concurrente; identidades fixture; DB',name)
